from itertools import permutations
from textwrap import wrap

# --- Словарь соответствия букв и позиций ---
letters_numbers_pairs = {
    'K': ['1', '3', '5', '6', '8'],  # K соответствует этим цифрам
    'I': ['2'],  # I = 2
    'D': ['4'],  # D = 4
    'H': ['7']  # H = 7
}

# --- Оригинальные словари расшифровки ---
dict_1 = {'KK': 'б', 'KI': 'о', 'DH': 'м', 'KK': 'б', 'AN': 'а'}
dict_2 = {'KK': 'б', 'KH': 'о', 'DI': 'м', 'KK': 'б', 'NA': 'а'}
dict_3 = {'KK': 'б', 'HD': 'о', 'IK': 'м', 'KK': 'б', 'NA': 'а'}
dict_4 = {'KK': 'б', 'ID': 'о', 'HK': 'м', 'KK': 'б', 'AN': 'а'}


# --- Функция для поиска буквы по цифре ---
def find_letter_by_number(number):
    for letter, numbers in letters_numbers_pairs.items():
        if str(number) in numbers:
            return letter
    return '?'  # Если цифра не найдена


# --- Функция перестроения словаря по Permutation ---
def remap_dict(permutation, original_dict):
    remapped = {}

    # Формируем пары (0,1), (2,3), (4,5), (6,7) из Permutation
    for i in range(0, len(permutation), 2):
        a, b = permutation[i], permutation[i + 1]

        # Находим буквы для текущей пары
        letter_a = find_letter_by_number(a)
        letter_b = find_letter_by_number(b)

        # Создаём новый ключ для словаря (например, KK, KI)
        new_key = f"{letter_a}{letter_b}"

        # Берём значение из исходного словаря (или по умолчанию '?')
        value = original_dict.get('KK', '?')  # Если ключ отсутствует, берём 'KK' как стандарт

        # Заполняем новый словарь
        remapped[new_key] = value

    return remapped


# --- Функции для расшифровки текста ---
def rm_noise(s):
    places = [3, 4, 6, 10, 11, 13, 14, 15]
    a = wrap(s, 16)
    r = ''
    for w in a:
        for p in places:
            r += w[p]
    return r


def shuffle(s, table):
    a = wrap(s, 8)
    r = ''
    for w in a:
        for i in table:
            r += w[i - 1]
    return r


def decode(s, table):
    a = wrap(s, 2)
    r = ''
    for w in a:
        if w in table:
            r += table[w]
        else:
            r += '?'
    return r


def calc_dict(sample, encoding, table):
    t = rm_noise(encoding)
    tnew = wrap(shuffle(t, table), 2)
    s = wrap(sample, 1)
    d = {}
    for i in range(len(s)):
        d[tnew[i]] = s[i]
    return d


a = ''
b = 'KEOIAKDKNDKHKILOMPPBLBMNDKMBAGEE'
c = 'KIHICKDKFHKHKCBAMAJBNBMNBGMBANBA'
d = 'MAKBNBMCGKMBDBKKMBPBBBMMENMBBEKE'


# --- Функция расшифровки с учётом Permutation ---
def ex(tab, permutation):
    # Динамическое создание словаря на основе Permutation
    updated_dict_1 = remap_dict(permutation, dict_1)
    updated_dict_2 = remap_dict(permutation, dict_2)
    updated_dict_3 = remap_dict(permutation, dict_3)
    updated_dict_4 = remap_dict(permutation, dict_4)

    d1 = calc_dict('бомб', b[0:16], tab)
    d2 = calc_dict('а___', b[16:32], tab)
    d3 = calc_dict('1___', d[0:16], tab)
    d4 = calc_dict('____', d[16:32], tab)

    # Объединяем все словари
    dic = d1 | d2 | d3 | d4 | updated_dict_1 | updated_dict_2 | updated_dict_3 | updated_dict_4

    result = decode(shuffle(rm_noise(a), tab), dic)

    # Записываем в файл
    with open(output_file, 'a', encoding='utf-8') as f:
        f.write(f"Permutation: {permutation}\n")
        f.write(f"Decoded Text: {result}\n\n")


output_file = "results_permutation.txt"

# Очищаем файл перед началом работы
with open(output_file, 'w', encoding='utf-8') as f:
    f.write("Starting decoding...\n\n")


# --- Чтение Permutation из valid_results.txt ---
def read_permutations_from_file(input_file):
    permutations = []
    with open(input_file, 'r', encoding='utf-8') as f:
        for line in f:
            if line.startswith("Permutation:"):
                permutation = list(map(int, line.strip().split("[")[1].split("]")[0].split(", ")))
                permutations.append(permutation)
    return permutations


# --- Генерация словарей на основе valid_results.txt ---
valid_permutations = read_permutations_from_file("results.txt")

# Применяем найденные Permutation
for perm in valid_permutations:
    ex(perm, perm)

print(f"Результаты сохранены в {output_file}")

